// Aviso diario de lo indispensable: cada mañana, si algo básico (huevos, arroz, arepas, queso…) está por acabarse y no está en la canasta,
// manda UNA notificación al celular. Lo opcional (aguacate, etc.) no avisa. Cada producto se puede marcar o desmarcar como indispensable desde Duración.
// Webhook (POST aviso-canasta): ver → qué productos son indispensables · esencial → marcar/desmarcar uno · probar → mandar el aviso ahora
const http = (o) => this.helpers.httpRequest(o);
const sd = $getWorkflowStaticData('global');
sd.esenciales = sd.esenciales || {};
let esWeb = false, b = {};
try { const w = $('Webhook').first(); if (w) { esWeb = true; b = w.json.body; if (typeof b === 'string') b = JSON.parse(b); } } catch (e) {}
b = b || {};
if (esWeb && b.token !== 'mercado-7d41c2a9e05b') return [{ json: { web: true, ok: false, error: 'token' } }];
const accion = esWeb ? (['ver', 'esencial', 'probar'].includes(b.accion) ? b.accion : 'ver') : 'avisar';

const norm = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const BASICOS = [/\bhuevos?\b/, /\barroz\b/, /\barepas?\b/, /\bquesos?\b/, /\bleche\b/, /\bpan\b/, /\baceite\b/, /\bsal\b/, /\bazucar\b/, /\bcafe\b/, /\bpapel higienico\b/, /\bpanales\b/];
const base = (p) => String(p.nombre || '').split(' · ')[0].trim();
const esEsencial = (p) => (p.id in sd.esenciales) ? !!sd.esenciales[p.id] : BASICOS.some(re => re.test(norm(base(p))));

if (accion === 'esencial') {
  const id = String(b.id || '');
  if (!/^[0-9a-fA-F-]{32,36}$/.test(id)) return [{ json: { web: true, ok: false, error: 'id' } }];
  sd.esenciales[id] = !!b.valor;
}

let productos = [];
try {
  const est = await http({ method: 'GET', url: 'http://localhost:5678/webhook/mercado-estado', json: true, timeout: 20000 });
  productos = Array.isArray(est && est.productos) ? est.productos : [];
} catch (e) {
  if (accion === 'avisar' || accion === 'probar') return [{ json: { web: esWeb, ok: false, error: 'estado' } }];
}

const hoy = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);   // hora de Colombia
const dias = (f) => Math.floor((Date.parse(hoy + 'T12:00:00Z') - Date.parse(String(f).slice(0, 10) + 'T12:00:00Z')) / 864e5);
// igual que Duración: «pronto» es desde el 85% de lo que suele durar; lo que ya está en la canasta no se avisa
const urgentes = productos
  .filter(p => !p.falta && p.duraDias > 0 && /^\d{4}-\d{2}-\d{2}/.test(p.ultimaCompra || '') && esEsencial(p))
  .map(p => ({ p, pct: dias(p.ultimaCompra) / p.duraDias }))
  .filter(x => x.pct >= 0.85)
  .sort((a, b) => b.pct - a.pct);

const ids = productos.filter(esEsencial).map(p => p.id);
// lo indispensable que YA está en la lista (falta) se recuerda a las 8 am y a las 5 pm hasta que se compre; lo que apenas se está acabando, solo en la mañana
const enLista = productos.filter(p => p.falta && esEsencial(p));
const franja = Number(new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(11, 13)) < 12 ? 'am' : 'pm';
const clave = hoy + ' ' + franja;
const yaAviso = sd.avisosHechos && sd.avisosHechos[clave];
// lo que está en la canasta con otra cantidad esta vez lo dice: «Carne molida (1 libra)»
const conCant = (p) => base(p) + (p.cantidad ? ' (' + String(p.cantidad).trim() + ')' : '');
const lee = (arr, f = base) => { const n = arr.map(x => f(x)); const l = n.length <= 4 ? n : n.slice(0, 4).concat('' + (n.length - 4) + ' más'); return l.length > 1 ? l.slice(0, -1).join(', ') + ' y ' + l[l.length - 1] : l[0]; };
let enviado = false;
if (accion === 'avisar' || accion === 'probar') {
  const porAcabar = (accion === 'probar' || franja === 'am') ? urgentes.map(x => x.p) : [];
  const partes = [];
  if (enLista.length) partes.push('Falta comprar: ' + lee(enLista, conCant) + '.');
  if (porAcabar.length) partes.push(lee(porAcabar) + (porAcabar.length === 1 ? ' se está acabando' : ' se están acabando') + '. Déjal' + (porAcabar.length === 1 ? 'o' : 'os') + ' en la canasta.');
  if (partes.length && (accion === 'probar' || !yaAviso)) {
    try {
      await http({ method: 'POST', url: 'http://localhost:5678/webhook/push-enviar', body: { token: 'mercado-7d41c2a9e05b', title: enLista.length ? '🛒 Toca ir a comprar' : 'Toca comprar', body: partes.join(' '), url: enLista.length ? './?ver=mercar' : './?ver=dura', tag: 'canasta' }, json: true, timeout: 15000 });
      enviado = true;
      if (accion === 'avisar') { const m = sd.avisosHechos || {}; m[clave] = 1; Object.keys(m).filter(k => k.slice(0, 10) < hoy).forEach(k => delete m[k]); sd.avisosHechos = m; }
    } catch (e) {}
  }
}
return [{ json: { web: esWeb, ok: true, accion, ids, urgentes: urgentes.length, enLista: enLista.length, enviado } }];
